  function s10(prefix){
    var n = String(Math.floor(10000000 + Math.random() * 89999999)), w = [8,6,4,2,3,5,9,7], sum = 0;
    for(var i = 0; i < 8; i++) sum += +n[i] * w[i];
    var ck = 11 - (sum % 11); ck = ck === 10 ? 0 : (ck === 11 ? 5 : ck);
    return prefix + n + ck + "TH";
  }
