  function thpStep(rows, g){ for(var i = 0; i < rows.length; i++) if(g <= rows[i][0]) return rows[i]; return null; }
  /* returns { p: THB } or { why: reason } · kg = chargeable (or actual for noVol services), dec = declared value THB */
  function thpPrice(a, cc, kg, dec){
    var S = THPR.svc[a.thp], g = Math.max(1, Math.ceil(kg * 1000)), r, z, t;
    if(a.thp === "EMS"){
      z = S.zone[cc]; if(!z) return { why:"ไม่ให้บริการปลายทางนี้" };
      if(g > z[1] * 1000) return { why:"เกินน้ำหนักสูงสุด " + z[1] + " กก. ของปลายทางนี้" };
      r = thpStep(S.bands, g); return r ? { p:r[1][z[0] - 1] } : { why:"เกินน้ำหนักที่รับ" };
    }
    if(a.thp === "CP"){
      z = S.zone[cc]; if(!z) return { why:"ไม่ให้บริการปลายทางนี้" };
      if(g <= 30000){ r = thpStep(S.bands, g); return { p:r[1][z - 1] }; }
      t = thpStep(S.perKg, g); return t ? { p:Math.ceil(g / 1000) * t[1][z - 1] } : { why:"เกิน 200 กก." };
    }
    if(a.thp === "EPK"){
      t = S.byCountry[cc]; if(!t) return { why:"เฉพาะปลายทางในสหภาพยุโรป" };
      r = thpStep(t, g); return r ? { p:r[1] } : { why:"เกิน 5 กก." };
    }
    if(a.thp === "CPP_DDU"){
      var side = null, col = -1;
      [["left", S.leftGroups], ["right", S.rightGroups]].forEach(function(x){ x[1].forEach(function(grp, j){ if(grp.indexOf(cc) >= 0){ side = x[0]; col = j; } }); });
      if(!side) return { why:"ไม่ให้บริการปลายทางนี้" };
      var T = S[side], kgUp = Math.ceil(g / 1000) * 1000, last = T.fixed[T.fixed.length - 1][0];
      if(kgUp <= last){ r = thpStep(T.fixed, kgUp); return { p:r[1][col] }; }
      t = thpStep(T.per, kgUp); return t ? { p:(kgUp / 1000) * t[1][col] } : { why:"เกินน้ำหนักที่รับ" };
    }
    if(a.thp === "CPP_DDP"){
      t = S.byCountry[cc]; if(!t) return { why:"ไม่ให้บริการปลายทางนี้" };
      var cap = { US:7500, SG:10000 }[cc]; if(cap && dec > cap) return { why:"มูลค่าของเกิน " + cap.toLocaleString("en-US") + " บาทต่อ Shipment" };
      var lastF = t.fixed[t.fixed.length - 1][0];
      if(g <= lastF){ r = thpStep(t.fixed, Math.ceil(g / 500) * 500); return { p:r[1] }; }
      if(!t.per.length) return { why:"เกินน้ำหนักสูงสุด " + lastF / 1000 + " กก. ของปลายทางนี้" };
      t = thpStep(t.per, g); return t ? { p:Math.ceil(g / 1000) * t[1] } : { why:"เกิน 200 กก." };
    }
    return { why:"ไม่มีอัตรา" };
  }

