  /* D-Post Inter service main series → tracking prefix (EX Express, EA Express All-in, DL Direct Lastmile, DA Direct Lastmile All-in,
     OT Other) + agent digit (1 UPS 2 FedEx 3 Aramex 4 DHL … 0 = not in the list) + service code. Tracking = series + agent digit +
     9 digits + destination ISO2 (same shape as FXA130658571NL); product code = series + spare 0 + agent + account + service. */
  var SERIES = { FS:["EX", 1, "XPS"], FedEx_Express:["EX", 2, "PRI"], Fastship_DHL_Promo:["EX", 4, "XPS"], FS_EcoXpress:["EX", 1, "XPV"], FS_BBULK:["EX", 2, "ECO"],
    FS_Extra_Allin:["EA", 1, "XPS"], FS_Yun_USA:["DA", 0, "ECO"], USPS_Des_Entry:["DA", 0, "USP"], Thaipost_Ems:["DL", 0, "ECO"], Thaipost_Epacket:["DL", 0, "ECO"], DHL_ECOM:["DL", 5, "ECO"],
    Fastship_DHL:["EX", 4, "XPS"], Aramex:["EX", 3, "XPS"], FS_Express_Allin:["EA", 3, "XPS"] };
  function fsTrack(a, cc){ if(a.s10) return a.s10 + rndCode(9, "0123456789") + "TH"; var x = SERIES[a.code] || ["OT", 0, "ECO"]; return x[0] + x[1] + rndCode(9, "0123456789") + cc; }
  function fsProduct(a){ var x = SERIES[a.code] || ["OT", 0, "ECO"]; return x[0] + "0" + x[1] + "1" + x[2]; }
  function agentTrack(a){ return a.prov === "UPS" ? "1Z" + rndCode(6, "0123456789ABCDEFGHJKLMNPRSTUVWXY") + rndCode(10, "0123456789") : rndCode(12, "0123456789"); }

