        var rec = flRecord("paid"); rec.track = FL.paid.track; rec.shipId = FL.paid.shipId; rec.paidAmt = T.total; CTRREG[rec.track] = rec;
        try{ if(ADM) ADM.add({ track:FL.paid.track, svc:o.a.name, cc:d.c.c, amt:T.total, rfq:false, paid:true, payName:pay.name, ddp:ddp, ddpPaid:ddp, rcv:FL.r.first + " " + FL.r.last, detail:"D-Post Inter · จ่ายออนไลน์ · รอฝากที่สาขา", ch:"D-Post Inter online" }); }catch(err){}
