    var h = (FF.truck.length ? '<div class="ff-banner"><span><b>' + FF.truck.length + '</b> รายการรออยู่ในรถรับของ</span><button type="button" class="fl-link" data-ff="go" data-v="3">ดูรถรับของ →</button></div>' : '') +
      '<h2>ขั้นตอนที่ 1 — รายละเอียดการจองและพัสดุ</h2><p style="margin:2px 0 16px"><button type="button" class="fl-link" data-ff="demo">กรอกตัวอย่าง</button> <span class="tcid add">POC</span></p>' +
      '<div class="ff-sec">ผู้รับปลายทาง</div><div class="fl-grid2">' +
      '<div class="fl-field full"><span>ประเทศปลายทาง</span><div class="fl-combo" id="ffCombo"><button type="button" class="fl-combo-btn" id="ffCountryBtn" aria-haspopup="listbox" aria-expanded="false">' + cflag(c.c) + '<span class="t"><b style="font-size:17px">' + c.en + '</b></span>' + IC.chev.replace("<svg", '<svg class="ch"') + '</button><div class="fl-pop" id="ffCPop" hidden><input id="ffCSearch" placeholder="ค้นหา" aria-label="ค้นหา" autocomplete="off"><div class="fl-list" id="ffCList" role="listbox"></div></div></div></div>' +
      '<div class="fl-zip">' + ffField("ffZip", ffZipNeeded(f) ? "รหัสไปรษณีย์" : "รหัสไปรษณีย์ (ไม่บังคับ)", '<input id="ffZip" data-ffi="zip" value="' + esc(f.zip) + '" autocomplete="off" role="combobox" aria-expanded="false">', e("ffZip")) + '<div class="fl-pop" id="ffZipPop" hidden role="listbox"></div><small class="fl-xs" id="ffZipNo" style="color:var(--freight-amber)" hidden>ไม่พบรหัสนี้ — กรุณากรอกเมืองและรัฐเอง</small></div>' +
      ffField("ffCity", "เมือง", '<input id="ffCity" data-ffi="city" value="' + esc(f.city) + '">', e("ffCity"), f.auto ? "ff-auto" : "") +
      ffField("ffState", "รัฐ / จังหวัด", '<input id="ffState" data-ffi="state" value="' + esc(f.state) + '">', e("ffState"), f.auto ? "ff-auto" : "") +
      (ffZipNeeded(f) ? '<p class="fl-xs fl-muted full" style="margin:-6px 0 0">พิมพ์เพื่อค้นหา — ระบบจะกรอกเมืองและรัฐให้อัตโนมัติ</p>' : '') +
      ffField("ffAddr", "ที่อยู่ผู้รับ", '<textarea id="ffAddr" data-ffi="addr" rows="2" maxlength="1000" placeholder="เลขที่ ถนน อาคาร">' + esc(f.addr) + '</textarea>', e("ffAddr"), "full") +
      ffField("ffName", "ชื่อผู้รับ", '<input id="ffName" data-ffi="name" maxlength="200" autocomplete="name" value="' + esc(f.name) + '">', e("ffName"), "full") +
      '<label class="fl-field' + (e("ffPhone") ? " bad" : "") + '"><span>เบอร์โทรผู้รับ</span><span class="fl-phone' + (e("ffPhone") ? " bad" : "") + '"><select data-ffi="th" aria-label="รหัสประเทศของเบอร์โทร"><option value="0"' + (f.th ? "" : " selected") + '>' + c.en + ' (+' + c.dial + ')</option><option value="1"' + (f.th ? " selected" : "") + '>Thailand (+66)</option></select><input id="ffPhone" data-ffi="phone" type="tel" inputmode="tel" placeholder="' + (f.th ? "81 234 5678" : "213 555 0100") + '" value="' + esc(f.phone) + '"></span>' + (e("ffPhone") ? '<small class="fl-err">กรอกเบอร์โทรโดยไม่ต้องใส่รหัสประเทศ เช่น 213 555 0100</small>' : '') + '</label>' +
      ffField("ffEmail", "อีเมลผู้รับ (ไม่บังคับ)", '<input id="ffEmail" data-ffi="email" type="email" inputmode="email" value="' + esc(f.email) + '">', m.indexOf("ffEmail") > -1 ? "กรอกอีเมลให้ถูกต้อง" : "") +
      '</div><hr class="ff-div"><div class="ff-sec">พัสดุ</div><div class="fl-grid2">' +
      ffField("ffWeight", "น้ำหนักโดยประมาณทั้งหมด (กก.)", '<input id="ffWeight" data-ffi="weight" inputmode="decimal" value="' + esc(f.weight) + '">', "") +
      ffField("ffBoxes", "จำนวนกล่องทั้งหมด", '<input id="ffBoxes" data-ffi="boxes" inputmode="numeric" value="' + esc(f.boxes) + '">', e("ffBoxes")) +
      '</div><div id="ffLive"></div>' +
      '<div class="ff-nav"><span></span><button type="button" class="fl-btn ink r" data-ff="next1">ถัดไป</button></div>';
