  function aqPay(){
    var c = aqCalc(), d = aqDest(), r = aqRounds()[AQ.round], tr = s10("EA");
    var slot = ["13:00–15:00", "15:00–17:00"][AQ.slot];
    var items = AQ.items.map(function(it){ return aqSp(it.sp).n + " " + nfmt(it.qty) + " " + aqSp(it.sp).u; }).join(", ");
    var lines = [["ค่าขนส่งทางอากาศ · " + c.boxes + " กล่อง", c.ship]];
    if(c.pkg) lines.push(["บรรจุภัณฑ์ Special Handling", c.pkg]);
    if(c.doc) lines.push(["ดำเนินการเอกสารส่งออก", c.doc]);
    var docsTxt = aqDocs().map(function(x){ return x.s; }).join(" · ");
    payThenTicket({
      track:tr, cc:d.cc,
      eyebrow:"Aquatic export booked", title:"จองรอบส่งสัตว์น้ำแล้ว",
      sub:"ปณท " + (AQ.docMode === "thp" ? "ยื่นเอกสารส่งออกกับกรมประมงให้แล้ว" : "ส่งเอกสารที่แนบให้กรมประมงตรวจแล้ว") + " นำสัตว์น้ำมาส่งที่ ปณ.นครปฐม ตามเวลานัด",
      steps:[{ t:"จองรอบ<br>&amp; Declare", s:"done" }, { t:"ชำระเงิน" }, { t:"เอกสาร &amp;<br>ตรวจสุขภาพ", s:"now" }, { t:"นำส่ง<br>ปณ.นครปฐม" }],
      rows:[["บริการ", "สัตว์น้ำสวยงาม · Special Handling<small>" + d.ap + " · ถึงใน " + d.tt + "</small>"], ["ปลายทาง", d.n], ["ผู้รับ", esc(AQ.rcvN) + "<small>" + esc(AQ.rcvA) + "</small>"],
        ["รอบส่ง", thDate(r.date) + "<small>นำส่ง " + thDate(r.drop) + " " + slot + "</small>"], ["สัตว์น้ำ", esc(items) + "<small>" + c.bags + " ถุง · " + c.boxes + " กล่อง</small>"], ["เอกสาร", docsTxt + "<small>" + (AQ.docMode === "thp" ? "ปณท ดำเนินการให้" : "ผู้ส่งยื่นเอง") + "</small>"]],
      payLabel:"ค่าบริการรวม", payNote:"ค่าธรรมเนียมกรมประมง (ถ้ามี) ชำระตามจริง", amountHtml:nfmt(c.total) + '<small>บาท</small>',
      hint:"เลขเดียวติดตามได้ทั้งสถานะเอกสารส่งออก การตรวจสุขภาพ และการขนส่งจนถึงผู้นำเข้า",
      branchLabel:"จุดรับฝาก", branches:["ปณ.นครปฐม (ศูนย์รับฝากสัตว์น้ำส่งออก)"],
      sync:["กรมประมง", "Dashboard เจ้าหน้าที่", "CRM"], trackBtn:"ติดตามรายการนี้ →",
      tc:"<b>อ้างอิง:</b> พธ. ขนส่งสัตว์น้ำ (รอบส่ง / Declare / รับฝากรายตัว) · ขร. ใบอนุญาต กรมประมง · ปณท × กรมประมง (ทะเบียนผู้ส่ง + เอกสาร 5 รายการ)",
      timeline:function(branch){ return [
        { title:"จองรอบ & Declare สัตว์น้ำ", sub:items, time:"วันนี้ " + hhmm(), done:true },
        { title:AQ.docMode === "thp" ? "ปณท ยื่น ร.9 · DOF4 · DOF11 ให้กรมประมง" : "กรมประมงตรวจเอกสารที่แนบ", sub:"สถานะภายใน: รอตรวจเอกสาร", time:"ภายใน " + thDate(r.cut) + " 16:00", current:true },
        { title:"ตรวจสุขภาพ & ออก Health Certificate", sub:"กรมประมง", time:thDate(r.drop) },
        { title:"นำส่ง & ตรวจสภาพบรรจุภัณฑ์", sub:branch + " · " + slot, time:thDate(r.drop) },
        { title:"ตรวจปล่อย & ขึ้นเครื่อง " + d.ap, sub:"Special Handling · ติดตามอุณหภูมิกล่อง", time:thDate(r.date) },
        { title:"ถึงปลายทาง & ส่งมอบผู้นำเข้า", sub:d.n, time:"ภายใน " + d.tt }
      ]; },
      onNew:function(){ AQ.step = 2; AQ.chk.sign = false; renderAq(); }
    }, { ref:"Aquatic export · " + d.n, lines:lines, total:c.total, credit:false,
      after:function(pay){ if(ADM && ADM.aq) ADM.aq({ track:tr, cc:d.cc, items:AQ.items.map(function(it){ return [aqSp(it.sp).n, nfmt(it.qty), aqSp(it.sp).u]; }), boxes:c.boxes, round:thDate(r.date), docMode:AQ.docMode }); } });
  }
  renderAq();


  /* =====================================================================
     Shared step-wizard for permit journeys (พระพุทธรูป / ต้นไม้)
     ใช้หน้าตาเดียวกับ journey สัตว์น้ำ (.aq-*) แต่สีตามหน่วยงาน
     ===================================================================== */
  function Wizard(root, o){
    var W = { st:o.state };
    function card(i, s){
      var n = i + 1, cur = W.st.step, k = n < cur ? "done" : n === cur ? "now" : "lock";
      return '<section class="aq-card ' + k + '"><div class="aq-ch"><span class="n">' + (k === "done" ? IC_OK.replace('stroke-width="3"', 'stroke-width="3" width="15" height="15"') : n) + '</span><h3>' + s.t + '</h3>' +
        (k !== "lock" ? s.tags.map(function(t){ return '<span class="tcid">' + t + '</span>'; }).join("") : "") + '<span class="sp"></span>' +
        (k === "done" ? '<button type="button" class="edit" data-wz="goto" data-v="' + n + '">แก้ไข</button>' : "") + '</div>' +
        (k === "done" ? '<p class="aq-sumline">' + s.sum() + '</p>' : k === "now" ? '<div class="aq-body">' + s.body() + (s.next !== false ? '<div class="aq-actions"><button type="button" class="aq-btn" data-wz="next" data-v="' + n + '"' + (s.can() ? "" : " disabled") + '>ถัดไป ' + IC_GO + '</button>' + (s.hint && !s.can() ? '<span class="msg">' + s.hint() + '</span>' : "") + '</div>' : "") + '</div>' : "") + '</section>';
    }
    W.render = function(){
      var cur = W.st.step;
      root.innerHTML = o.hero() +
        '<ol class="aq-steps">' + o.steps.map(function(s, i){ var n = i + 1; return '<li class="' + (n < cur ? "done" : n === cur ? "now" : "") + '"><i>' + (n < cur ? "✓" : n) + '</i><span>' + s.t + '</span></li>'; }).join("") + '</ol>' +
        '<div class="aq-grid"><div class="aq-col">' + o.steps.map(function(st, i){ return card(i, st); }).join("") + '</div><aside class="aq-side">' + o.summary() + '</aside></div>';
    };
    root.addEventListener("click", function(e){
      var b = e.target.closest("[data-wz]"); if(!b || b.disabled) return;
      var a = b.dataset.wz, v = b.dataset.v;
      if(b.tagName === "A") e.preventDefault();
      if(a === "next"){ W.st.step = Math.max(W.st.step, +v + 1); W.render(); var nx = root.querySelector(".aq-card.now"); if(nx) nx.scrollIntoView({ behavior:"smooth", block:"start" }); return; }
      if(a === "goto"){ W.st.step = +v; W.render(); return; }
      if(o.act(a, v, b) !== false) W.render();
    });
    root.addEventListener("change", function(e){ if(o.chg(e.target) !== false) W.render(); });
    return W;
  }
  function wzSeg(act, list, cur){ return '<div class="aq-seg">' + list.map(function(x){ return '<button type="button" data-wz="' + act + '" data-v="' + x[0] + '" class="' + (cur === x[0] ? "on" : "") + '"><b>' + x[1] + '</b><small>' + x[2] + '</small></button>'; }).join("") + '</div>'; }
  function wzSel(key, list, cur, attr){ return '<select ' + (attr || "data-wf") + '="' + key + '">' + list.map(function(x){ var v = typeof x === "string" ? x : x[0], t = typeof x === "string" ? x : x[1]; return '<option value="' + esc(v) + '"' + (v === cur ? " selected" : "") + '>' + t + '</option>'; }).join("") + '</select>'; }
  function wzWarn(cls, html){ return '<div class="aq-warn ' + (cls || "") + '"><span>' + IC_WARN + '</span><div>' + html + '</div></div>'; }
  function wzOk(html){ return '<div class="aq-warn" style="background:var(--good-bg);color:var(--good)"><span>' + IC_OK.replace('stroke-width="3"', 'stroke-width="3" width="17" height="17"') + '</span><div>' + html + '</div></div>'; }
  function wzSvc(kg, cc, cur, list){
    var c = COUNTRIES.filter(function(x){ return x.code === cc; })[0] || COUNTRIES[0], ch = Math.max(0.5, Math.ceil(kg * 2) / 2);
    var S0 = [["ems", "EMS World", "เร็ว · ติดตามได้ทุกช่วง", 520, 260, "4–7 วัน"], ["cpd", "Courier Post (DHL)", "ด่วนพิเศษ · ส่งถึงมือ", 980, 420, "2–4 วัน"], ["air", "พัสดุทางอากาศ (Air Parcel)", "ประหยัด · เหมาะของหนัก", 410, 190, "7–14 วัน"]].filter(function(s){ return !list || list.indexOf(s[0]) > -1; });
    return S0.map(function(s){ return { k:s[0], n:s[1], d:s[2], tt:s[5], p:Math.round((s[3] + s[4] * Math.max(0, ch - 0.5)) * c.zone) }; });
  }
  function wzSvcHtml(opts, cur){
    return '<div class="aq-rounds">' + opts.map(function(s){ return '<label class="aq-round"><input type="radio" name="wzsvc' + opts.length + cur.length + '" data-wz="svc" data-v="' + s.k + '"' + (s.k === cur ? " checked" : "") + '><div><b>' + s.n + '</b><p>' + s.d + ' · ' + s.tt + '</p></div><span class="r"><b>' + baht(s.p) + '</b>ค่าส่ง</span></label>'; }).join("") + '</div>';
  }
  function wzPhoto(t, tone){
    return 'data:image/svg+xml;utf8,' + encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 96 96"><rect width="96" height="96" fill="#ece8df"/><path d="M48 18a8 8 0 1 1 0 16 8 8 0 0 1 0-16zM34 46c3-6 8-9 14-9s11 3 14 9l4 18H30zM22 76c6-8 15-11 26-11s20 3 26 11z" fill="' + tone + '"/><text x="48" y="92" font-size="10" text-anchor="middle" fill="#5f6b71" font-family="sans-serif">' + t + '</text></svg>');
  }

  /* =====================================================================
     JOURNEY · ส่งพระพุทธรูป / วัตถุมงคลไปต่างประเทศ (กรมศิลปากร)
     อ้างอิง: พ.ร.บ.โบราณสถาน โบราณวัตถุ ศิลปวัตถุ และพิพิธภัณฑสถานแห่งชาติ พ.ศ. 2504
     ต้องได้รับอนุญาตจากอธิบดีกรมศิลปากรก่อนส่งออก ทั้งของเก่าและของใหม่ · ยื่นผ่าน NSW กรมศิลปากร
     ===================================================================== */
  var BKIND = [["statue", "พระพุทธรูปบูชา"], ["amulet", "พระเครื่อง / วัตถุมงคล"], ["art", "ศิลปวัตถุอื่น ๆ"]];
  var BAGE = [["new", "สร้างใหม่ (ไม่ถึง 100 ปี)"], ["old", "เก่า 100 ปีขึ้นไป"], ["unk", "ไม่ทราบอายุ"]];
  var BCOND = [["ok", "องค์สมบูรณ์"], ["dmg", "ชำรุด"], ["part", "เป็นชิ้นส่วน เช่น เศียร"]];
  var BMUS = ["สำนักพิพิธภัณฑสถานแห่งชาติ (กรุงเทพฯ)", "พิพิธภัณฑสถานแห่งชาติ เชียงใหม่", "พิพิธภัณฑสถานแห่งชาติ เชียงราย", "พิพิธภัณฑสถานแห่งชาติ สงขลา", "พิพิธภัณฑสถานแห่งชาติ ถลาง (ภูเก็ต)", "พิพิธภัณฑสถานแห่งชาติ อุบลราชธานี", "พิพิธภัณฑสถานแห่งชาติ อุดรธานี"];
  var BU = { step:1, who:"person", name:"คุณวิชัย ศรีสุข", idOk:false,
    items:[{ kind:"statue", name:"พระพุทธรูปปางมารวิชัย หน้าตัก 9 นิ้ว", mat:"สำริด", h:35, w:24, qty:1, age:"new", cond:"ok", kg:4.2 },
           { kind:"amulet", name:"พระสมเด็จ (พิมพ์ใหญ่)", mat:"ผงพุทธคุณ", h:4, w:2.5, qty:3, age:"new", cond:"ok", kg:0.1 }],
    proof:"ใบเสร็จร้านพุทธศิลป์ เสาชิงช้า", photos:{}, insp:"photo", mus:BMUS[0], slot:0,
    cc:"US", rcvN:"Somchai Lee", rcvA:"2140 Ocean Ave, San Francisco, CA 94127", svc:"ems", pack:"crate", ins:true, dv:18000, sign:false };
  function buKg(){ return BU.items.reduce(function(a, it){ return a + it.kg * it.qty; }, 0) + (BU.pack === "crate" ? 2.5 : 0.6); }
  function buVerdict(it){
    if(it.age === "old") return ["bad", "เป็นโบราณวัตถุ (อายุ 100 ปีขึ้นไป) — โดยทั่วไปไม่อนุญาตให้นำออกนอกราชอาณาจักร"];
    if(it.cond === "part") return ["bad", "เป็นชิ้นส่วนพระพุทธรูป — ไม่อนุญาตให้นำออก"];
    if(it.cond === "dmg") return ["bad", "พระพุทธรูปชำรุด — ไม่อนุญาตให้นำออก"];
    if(it.age === "unk") return ["warn", "ไม่ทราบอายุ — ต้องนำของจริงไปให้คณะกรรมการตรวจอายุที่พิพิธภัณฑสถาน"];
    return ["ok", "ยื่นขออนุญาตได้"];
  }
  function buBlocked(){ return BU.items.some(function(it){ return buVerdict(it)[0] === "bad"; }); }
  function buNeedMuseum(){ return BU.items.some(function(it){ return buVerdict(it)[0] === "warn"; }); }
  function buPhotosOk(){ return BU.items.every(function(it, i){ return BU.photos[i] !== false; }); }
  function buCost(){
    var o = wzSvc(buKg(), BU.cc).filter(function(s){ return s.k === BU.svc; })[0];
    var pack = BU.pack === "crate" ? 650 : BU.pack === "box" ? 180 : 0, ins = BU.ins ? Math.max(60, Math.round(BU.dv * 0.009)) : 0, svc = 300;
    return { ship:o.p, sname:o.n, pack:pack, ins:ins, svc:svc, total:o.p + pack + ins + svc };
  }
  var buRoot = document.getElementById("buRoot");
