      if(a === "bdel"){ BU.items.splice(+v, 1); return; }
      if(a === "who"){ BU.who = v; BU.idOk = false; return; }
      if(a === "idok"){ withSpinner(b, "กำลังยืนยันตัวตน…", function(){ BU.idOk = true; BUW.render(); }); return false; }
      if(a === "insp"){ BU.insp = v; return; }
