  var PFORM = [["rooted", "ต้นมีราก"], ["cut", "กิ่ง / หน่อ"], ["seed", "เมล็ด"], ["flower", "ไม้ตัดดอก"], ["tc", "เนื้อเยื่อในขวด"]];
  var PCITES = /กล้วยไม้|orchid|dendrobium|paphiopedilum|รองเท้านารี|หม้อข้าวหม้อแกงลิง|nepenthes|ปรง|cycas|cycad|กระบองเพชร|cactus|cactaceae/i;
  var PIMP = { AU:"ออสเตรเลียต้องมี Import Permit และตรวจเข้มงวดมาก", US:"สหรัฐฯ บางชนิดต้องมี Import Permit และพืชมีรากต้องไม่ติดวัสดุปลูก", CA:"แคนาดาบางชนิดต้องมี Import Permit" };
  var PL = { step:1, who:"nursery", sso:true, agent:true, nreg:true, name:"สวนกล้วยไม้บางใหญ่",
    items:[{ name:"มอนสเตอร่า (Monstera deliciosa)", form:"rooted", qty:6 }, { name:"กล้วยไม้สกุลหวาย (Dendrobium)", form:"rooted", qty:20 }],
    soil:true, bare:false, cc:"JP", rcvN:"Hana Garden Co., Ltd.", rcvA:"3-5-1 Nishi-Shinjuku, Tokyo 160-0023", ip:false,
    insp:"third", slot:0, docMode:"thp", up:{}, svc:"ems", pack:"vent", sign:false };
  function plCites(){ return PL.items.some(function(it){ return PCITES.test(it.name); }); }
  function plImp(){ return PIMP[PL.cc] || ""; }
  function plKg(){ return PL.items.reduce(function(a, it){ return a + it.qty * ({ rooted:0.35, cut:0.08, seed:0.01, flower:0.05, tc:0.12 }[it.form] || 0.2); }, 0) + 0.8; }
  function plDocs(){
    var d = [{ k:"pk7", n:"พ.ก.7 · คำขอใบรับรองสุขอนามัยพืช", by:"กรอกจากข้อมูลที่ Declare", auto:true }, { k:"pc", n:"Phytosanitary Certificate (ePhyto)", by:"กรมวิชาการเกษตร · ส่งถึงปลายทางผ่าน NSW / ePhyto Hub" }];
    if(plCites()) d.push({ k:"cites", n:"หนังสืออนุญาตส่งออกพืชอนุรักษ์ (CITES)", by:"กรมวิชาการเกษตร · ด่านตรวจพืช" });
    if(plImp()) d.push({ k:"ip", n:"Import Permit ของประเทศปลายทาง", by:"ผู้รับขอจากหน่วยงานปลายทาง", self:true });
    d.push({ k:"inv", n:"Invoice & Packing list", by:"สร้างอัตโนมัติจากรายการพืช", auto:true });
    return d;
  }
  function plDocsOk(){ return plDocs().every(function(x){ return x.auto || (x.self ? PL.ip : (PL.docMode === "thp" || PL.up[x.k])); }); }
  function plCost(){
    var o = wzSvc(plKg(), PL.cc, null, ["ems", "cpd", "air"]).filter(function(s){ return s.k === PL.svc; })[0];
    var pack = PL.pack === "vent" ? 150 : 0, doc = PL.docMode === "thp" ? 350 + (plCites() ? 200 : 0) : 0;
    return { ship:o.p, sname:o.n, pack:pack, doc:doc, total:o.p + pack + doc };
  }
