    var day = ["อ. 6 ต.ค.", "พ. 7 ต.ค.", "พฤ. 8 ต.ค."][PL.slot], place = PL.insp === "third" ? "ที่สวน (Third Party)" : "ด่านตรวจพืช สุวรรณภูมิ";
    var lines = [["ค่าส่ง · " + c.sname, c.ship]]; if(c.pack) lines.push(["บรรจุภัณฑ์ระบายอากาศ", c.pack]); if(c.doc) lines.push(["ยื่นเอกสารแทน", c.doc]);
