      rows:[["บริการ", c.sname + " · ต้นไม้/พืช<small>Phytosanitary" + (plCites() ? " + CITES" : "") + "</small>"], ["ปลายทาง", cn], ["ผู้รับ", esc(PL.rcvN) + "<small>" + esc(PL.rcvA) + "</small>"], ["พืช", esc(items) + "<small>Bare-root</small>"], ["ตรวจพืช", day + "<small>" + place + "</small>"], ["เอกสาร", docs]],
