  function cxConnected(k, name){
    cxH.hidden = true;
    CX.channels.push({ k:k, name:name, active:true, products:k === "shopify" ? 128 : 64, at:today() });
    var list = CX_ORDERS[k].map(function(o){ var x = JSON.parse(JSON.stringify(o)); x.k = k; x.store = name; x.id = "#" + (k === "shopify" ? "SC" : "WC") + x.n; return x; });
    CX.orders = list.concat(CX.orders);
    $c("cxStoreName").textContent = name;
    renderCxChannels(); cxFlow(1);
    cxLogAll("<span class='in'>← " + CXP[k].name + " connected · imported " + list.length + " unfulfilled orders</span>");
    setTimeout(function(){ cxView("cxOrders"); CX.filter = "new"; renderCxOrders(); cxFlow(2); }, 650);
  }

  /* ---- Order Feed ---- */
  var CX_LOG = [];
