        if(CX.pulled[c.k]) return; CX.pulled[c.k] = true;
        var x = JSON.parse(JSON.stringify(CX_NEW[c.k])); x.k = c.k; x.store = c.name; x.id = "#" + (c.k === "shopify" ? "SC" : "WC") + x.n; x.fresh = true;
        CX.orders.unshift(x); added++;
