      o.items.map(function(it){ return '<tr><td>' + esc(it.name) + '<br><span style="color:var(--ink-dim);font-size:12px">' + it.sku + '</span></td><td class="cx-date">' + it.hs + '</td><td class="n">' + it.g + ' g</td><td class="n">฿' + it.v.toLocaleString() + '</td><td class="n">' + it.q + '</td><td class="n"><b>฿' + (it.v * it.q).toLocaleString() + '</b></td></tr>'; }).join("") +
      '</tbody></table></div><div class="tot"><span>Total Declare Value</span><b>' + o.items.reduce(function(a, it){ return a + it.v * it.q; }, 0).toLocaleString() + ' THB</b></div>';
    pop.hidden = false;
