  /* ---------- tracking view · modelled on D-Post Inter Track & Trace ----------
     One tracking number shows the main status (5 steps), the sub-status events under each one, and physical
     evidence (parcel photos taken at the hub). Journeys still call renderTimeline(steps[, meta]); their steps are
     grouped into the 5 main statuses here. Tracking numbers use D-Post Inter's main series as prefix (EX/EA/DL/DA/OT). */
  var FT_MAIN = ["สร้างใบจ่าหน้าแล้ว", "กำลังเข้ารับพัสดุ", "ถึงศูนย์กระจายสินค้า", "อยู่ระหว่างการขนส่ง", "จัดส่งสำเร็จ"];
  var FT_IC = [
    '<path d="M12 3 20 7.5v9L12 21l-8-4.5v-9z"/><path d="M4 7.5 12 12l8-4.5M12 12v9"/>',
    '<path d="M2 6h12v10H2zM14 9h4l3 3v4h-7"/><circle cx="6" cy="18" r="2"/><circle cx="17" cy="18" r="2"/>',
    '<path d="M3 21V9l9-6 9 6v12"/><path d="M8 21v-7h8v7"/>',
    '<path d="M2 16l20-8-6 12-3-5-5-1z"/>',
    '<path d="M20 6 9 17l-5-5"/>'
  ];
  var FT_REG = {};
  var FT_DEMO = { track:"EX2130658571NL", agent:"877200465780", agentName:"FedEx", dest:"Netherlands (NL)", svc:"EX022XPV · FedEx International Economy",
    groups:[
      [0, [["Shipment information sent to courier", "", "15 ก.ย. 2026 11:02"]]],
      [1, [["Pickup Arrangement In Progress", "Laksi, Bangkok", "15 ก.ย. 2026 12:16"]]],
      [2, [["Received at D-Post Inter Facility", "Laksi, Bangkok", "15 ก.ย. 2026 16:04"], ["พัสดุได้รับการยืนยันส่งออกจาก D-Post Inter แล้ว", "Laksi, Bangkok", "16 ก.ย. 2026 10:31", true]]],
      [3, [["Agent Pickup at D-Post Inter Facility", "Laksi, Bangkok", "16 ก.ย. 2026 10:31"], ["Picked up", "BANGKOK, Thailand", "16 ก.ย. 2026 15:48"], ["Left courier origin facility", "BANGKOK, Thailand", "16 ก.ย. 2026 18:45"], ["Departed FedEx hub", "SAMUTPRAKARN, Thailand", "17 ก.ย. 2026 02:10"], ["International shipment release - Import", "LIEGE, Belgium", "19 ก.ย. 2026 07:40"], ["On FedEx vehicle for delivery", "NIJMEGEN, Netherlands", "22 ก.ย. 2026 08:05"]]],
      [4, [["Delivered", "NIJMEGEN, Netherlands (Holland)", "22 ก.ย. 2026 15:15"]]]
    ], done:{ day:"วันอังคาร", date:"22 กันยายน" } };

  function ftStage(t){
    if(/ส่งถึง|นำจ่ายถึง|จัดส่งสำเร็จ|Delivered|ส่งเข้าคลัง Amazon/i.test(t)) return 4;
    if(/ขนส่ง|ออกเดินทาง|ขึ้นเครื่อง|ขึ้นเรือ|ศุลกากร|ออกจากศูนย์|ส่งต่อผู้ให้บริการ|จัดส่งแล้ว|ส่งต่อ|Departed|Picked up/i.test(t)) return 3;
    if(/ถึงคลัง|ศูนย์|สาขา|รับฝาก|ชั่ง|หย่อน|เคาน์เตอร์|ชำระ|Facility/i.test(t)) return 2;
    if(/รับสินค้า|เข้ารับ|นัด|รถ|Pickup/i.test(t)) return 1;
    return 0;
  }
  /* turn a journey's step list into the Track & Trace shape */
  function ftFromSteps(steps, meta){
    var groups = {}, stage = 0;
    steps.forEach(function(s){
      if(!s.done && !s.current) return;
      var g = ftStage(s.title); if(g < stage) g = stage; stage = g;
      (groups[g] = groups[g] || []).push([s.title, s.sub || "", s.time || "", g === 2 && s.done]);
    });
    return { track:(meta && meta.track) || document.getElementById("trackInput").value.trim() || "—", agent:meta && meta.agent, agentName:meta && meta.agentName,
      dest:(meta && meta.dest) || "—", svc:meta && meta.svc, groups:Object.keys(groups).map(function(k){ return [+k, groups[k]]; }), eta:meta && meta.eta, current:stage };
  }
  function ftPhoto(i){
    var c = ["#c8a27a", "#b9925f", "#d8c1a0"][i % 3];
    return '<svg viewBox="0 0 40 40" aria-hidden="true"><rect width="40" height="40" rx="5" fill="#3b4048"/><path d="M8 16 20 10l12 6v14l-12 6-12-6z" fill="' + c + '"/><path d="M8 16l12 6 12-6M20 22v14" stroke="#7a5b3a" stroke-width="1" fill="none"/><rect x="21" y="24" width="8" height="5" fill="#fff" opacity=".9"/></svg>';
  }
  function renderTimeline(steps, meta){
    var d = Array.isArray(steps) ? ftFromSteps(steps, meta) : FT_DEMO;
    var cur = d.current != null ? d.current : Math.max.apply(null, d.groups.map(function(g){ return g[0]; }));
    FT_REG[d.track] = d;
    var last = d.groups.length ? d.groups[d.groups.length - 1][1].slice(-1)[0] : null;
    var h = '<div class="ft-head"><div><div class="ft-no">หมายเลขติดตามพัสดุ : <b>' + esc(d.track) + '</b></div>' +
      (d.agent ? '<div class="ft-agent">Agent Tracking' + (d.agentName ? " (" + esc(d.agentName) + ")" : "") + ' : <button type="button" class="ft-chip" data-ftcopy="' + esc(d.agent) + '">' + esc(d.agent) + ' <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="9" y="9" width="11" height="11" rx="2"/><path d="M5 15V5a2 2 0 0 1 2-2h10"/></svg></button></div>' : '') +
      (d.svc ? '<div class="ft-svc">Service : <code>' + esc(d.svc) + '</code></div>' : '') +
      '<div class="ft-dest">ประเทศปลายทาง : ' + esc(d.dest) + '</div></div>' +
      '<div class="ft-cur">สถานะปัจจุบัน : <b class="' + (cur === 4 ? "ok" : "") + '">' + (cur === 4 ? "Delivered" : FT_MAIN[cur]) + '</b></div></div>' +
      '<ol class="ft-steps">' + FT_MAIN.map(function(m, i){ return '<li class="' + (i < cur ? "done" : i === cur ? "now" : "") + '"><i><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">' + FT_IC[i] + '</svg></i><span>' + m + '</span></li>'; }).join("") + '</ol>';
    if(cur === 4 && d.done) h += '<div class="ft-big"><b>ส่งพัสดุสำเร็จแล้ว</b><span class="day">' + d.done.day + '</span><span class="date">' + d.done.date + '</span></div>';
    else if(last) h += '<div class="ft-big wait"><b>สถานะล่าสุด</b><span class="date sm">' + esc(last[0]) + '</span>' + (d.eta ? '<span class="day">' + esc(d.eta) + '</span>' : '') + '</div>';
    h += '<div class="ft-tl">' + d.groups.slice().reverse().map(function(g, gi){
      var ev = g[1].slice().reverse(), head = ev[0];
      return '<section class="ft-grp' + (gi === 0 ? " latest" : "") + '"><div class="ft-gh"><b>' + FT_MAIN[g[0]] + '</b><span>' + esc(head[2]) + '</span></div>' +
        ev.map(function(e){ return '<div class="ft-ev"><div class="t"><b>' + esc(e[0]) + '</b><span>' + esc(e[2]) + '</span></div>' + (e[1] ? '<small>' + esc(e[1]) + '</small>' : '') +
          (e[3] ? '<div class="ft-ph">' + [0, 1, 2].map(ftPhoto).join("") + '<span><b>รูปภาพพัสดุ</b><small>ถ่าย ณ ศูนย์กระจายสินค้า</small></span><button type="button" class="ft-full" data-ftph="1">ดูขนาดเต็ม</button></div>' : '') + '</div>'; }).join("") + '</section>';
    }).join("") + '</div>';
    document.getElementById("timelineBody").innerHTML = h;
  }
  renderTimeline();
  document.getElementById("trackBtn").addEventListener("click", function(){
    var q = document.getElementById("trackInput").value.trim().toUpperCase(), d = FT_REG[q];
    if(d){ var keep = FT_DEMO; FT_DEMO = d; renderTimeline(); FT_DEMO = keep; } else renderTimeline();
  });
  document.getElementById("trackInput").addEventListener("keydown", function(e){ if(e.key === "Enter") document.getElementById("trackBtn").click(); });
  document.getElementById("timelineBody").addEventListener("click", function(e){
    var c = e.target.closest("[data-ftcopy]");
    if(c){ try{ navigator.clipboard.writeText(c.dataset.ftcopy); }catch(err){} c.classList.add("ok"); return; }
    if(e.target.closest("[data-ftph]")){ evPhotos(e.target.closest(".ft-ph")); }
  });


