  (function(){
    var s = document.getElementById("j-va"); if(!s) return;
    s.addEventListener("input", function(e){
      var t = e.target;
      if(t.dataset.va && t.dataset.va !== "ok"){ VA.f[t.dataset.va] = t.value; return; }
      if(t.dataset.vap){ VA.pre[t.dataset.vap] = t.value; var b = s.querySelector('[data-vax="pre"]'); if(b) b.disabled = !vaPreOk(); }
    });
    s.addEventListener("change", function(e){ var t = e.target; if(t.dataset.va === "ok") VA.ok = t.checked; if(t.dataset.vap === "store") VA.pre.store = t.value; });
    s.addEventListener("click", function(e){
      var c = e.target.closest("[data-vacopy]"); if(c){ vaCopy(c, c.dataset.vacopy); return; }
      var b = e.target.closest("[data-vax]"); if(!b) return;
      var a = b.dataset.vax, x = VA.items[+b.dataset.i];
      if(a === "demo"){ VA.f.first = "Pimchanok"; VA.f.last = "Srisuk"; VA.f.addr = "99/1 ถ.แจ้งวัฒนะ แขวงทุ่งสองห้อง เขตหลักสี่ กรุงเทพฯ"; VA.f.zip = "10210"; if(!VA.f.phone) VA.f.phone = "081 234 5678"; if(!VA.f.email) VA.f.email = "pimchanok@example.com"; VA.ok = true; VA.err = ""; }
      else if(a === "reg"){
        var f = VA.f, miss = !f.first.trim() || !f.last.trim() || digits(f.phone).length < 9 || !emailOk(f.email) || !f.addr.trim() || !/^\d{5}$/.test(f.zip);
        if(miss) VA.err = "กรอกชื่อ นามสกุล เบอร์ อีเมล ที่อยู่ และรหัสไปรษณีย์ 5 หลักให้ครบ";
        else if(!VA.ok) VA.err = "กดยอมรับข้อตกลงและเงื่อนไขก่อนสมัคร";
        else { VA.err = ""; VA.member = "VA-2026-0" + (1000 + Math.floor(Math.random() * 8999)); VA.stage = "home"; window.scrollTo({ top:0 }); }
      }
      else if(a === "wh") VA.wh = b.dataset.v;
      else if(a === "pre"){
        if(!vaPreOk()) return;
        var row = { id:VA.member, n:"คุณ" + VA.f.first + " " + VA.f.last.slice(0, 1) + ".", store:VA.pre.store + " · " + VA.pre.tr.trim(), kg:0, fee:0, st:"pre", item:VA.pre.item.trim(), val:+VA.pre.val || 0 };
        VA.items.unshift(row); try{ if(ADM && ADM.va) ADM.va(row); }catch(err){}
        VA.pre = { store:VA.pre.store, tr:"", item:"", val:"" };
      }
      else if(a === "sim" && x){ x.st = "in"; x.kg = Math.round((0.6 + Math.random() * 2.4) * 10) / 10; }
      else if(a === "bill" && x){ x.fee = Math.round(420 + x.kg * 360); x.st = "bill"; }
      else if(a === "pay" && x){
        openPayment({ ref:"Virtual Address " + x.id, lines:[["ค่าส่งเข้าไทย · " + x.store, x.fee]], total:x.fee, ddp:0, allin:false, credit:false, noCash:true,
          onPaid:function(pay){ x.st = "paid"; x.rc = pay.receipt || pay.ref || "RC-VA"; vaRender(); } });
        return;
      }
      vaRender();
    });
    document.addEventListener("click", function(e){ if(e.target.closest('[data-journey="va"], .modesw button, .apptab')) setTimeout(vaRender, 0); });
    vaRender();
  })();

