    var fab = document.getElementById("fyFab");
    fab.setAttribute("aria-expanded", String(FY.open)); fab.setAttribute("aria-label", FY.open ? "ปิดแชท ผู้ช่วย D-Post" : "เปิดแชท ผู้ช่วย D-Post");
    fab.innerHTML = FY.open ? '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"><path d="M6 6l12 12M18 6 6 18"/></svg>' : '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 5h16v11H9l-5 4z"/><path d="M8 10h8M8 13h5"/></svg>';
    if(FY.open){ fyStart(); setTimeout(function(){ document.getElementById("fyTx").focus(); }, 40); }
