    document.querySelectorAll(".apptab-j").forEach(function(b){ var on = user && !track && b.dataset.journey === curJourney; b.classList.toggle("active", on); if(on) b.setAttribute("aria-current", "page"); else b.removeAttribute("aria-current"); });
