    var prog = closed ? "" : '<ol class="su-prog" aria-label="ขั้นตอนฝากซื้อ">' + ["ส่งคำขอ", "ชำระ", "สั่งซื้อ", "ร้านส่ง", "ถึงโกดัง"].map(function(t, i){ var c = i < step || (i === 4 && step === 4) ? "done" : i === step ? "now" : ""; return '<li class="' + c + '"' + (c === "now" ? ' aria-current="step"' : "") + '><i></i><span>' + t + '</span></li>'; }).join("") + '</ol>';
