      panel = suCall("success", tt, "ชำระค่าสินค้าแล้ว " + SI.baht(o.paid) + (o.credited ? " · คืนเป็นเครดิต " + SI.baht(o.credited) + " แล้ว" : ""), "", o.credited ? '<div class="su-call-a">' + suNavBtn("ถอนเป็นเงินสด", "acct", "credit") + '</div>' : "");
