    var items = '<section class="su-card"><h3 class="su-h3">สินค้า</h3><ul class="su-items">' + o.items.map(function(it){ return '<li><b>' + esc(it.title || o.store) + ' × ' + it.qty + '</b>' + (it.opt ? '<small>' + esc(it.opt) + '</small>' : "") + (it.price ? '<small class="su-mono">' + SI.fx(it.price, cur) + ' / ชิ้น</small>' : "") + (it.url ? '<a class="su-link" href="' + esc(it.url) + '" target="_blank" rel="noopener noreferrer">เปิดลิงก์สินค้า' + suI("ext") + '</a>' : "") + '</li>'; }).join("") + '</ul>' + (o.note ? '<p class="su-notebox"><b>หมายเหตุของคุณ: </b>' + esc(o.note) + '</p>' : "") + '</section>';
