      suIn("เบอร์โทรศัพท์", "prof.phone", { type:"tel", max:15 }) + suIn("อีเมล", "prof.email", { type:"email" }) + '</div>' + suBtn("บันทึกข้อมูลส่วนตัว", "", { submit:1, cls:"sec" }) + '</form></section>';
