        box.innerHTML = '<div class="ad-log" id="rbLog"></div>';
        var L = ["<span class='in'>→ POST /api/v1/order/rebook  " + s.ptr + "</span>", "<span class='d'>  payload: receiver, items, hs=" + s.hs + "</span>", "<span class='ok'>← 200 OK  booking=confirmed  label=reissued  (1.2s)</span>"], k = 0;
        (function t(){ if(k >= L.length){ audit("Rebook กับ YunExpress · ได้ Label ใหม่ (เลขเดิม)"); toast("YunExpress ยืนยัน Rebook แล้ว"); return; } var d = document.createElement("div"); d.innerHTML = L[k++]; document.getElementById("rbLog").appendChild(d); setTimeout(t, 450); })();
        return;
