    function f12Click(a, b){
      var op = b.dataset.op, v = b.getAttribute("data-v") || "";
      if(a === "pk"){
        if(op === "agent") PK.agent = +v;
        else if(op === "req"){ PK.st = "req"; toast("ส่งขออนุมัติแล้ว · รอ Pricing Manager"); }
        else if(op === "approve"){ PK.st = "ok"; toast("อนุมัติแล้ว · ราคารอบ พ.ย. 2569 active และขายได้ทันที"); }
        else if(op === "reset") PK.st = "draft";
        else if(op === "group") PK.group = v;
        render(); return true;
      }
      if(a === "ab"){
        if(op === "inv") AB.inv = +v;
        else if(op === "claim"){ AB.claim[v] = true; toast(v === "partner" ? "เปิดเคส dispute น้ำหนักกับ partner แล้ว (mock)" : "ออกใบแจ้งหนี้ส่วนต่างให้ลูกค้าแล้ว (mock)"); }
        render(); return true;
      }
      if(a === "pl"){
        if(op === "dim"){ PL.dim = v; PL.pick = null; } else if(op === "pick") PL.pick = +v;
        render(); return true;
      }
      return false;
    }
    function f12Change(t){
      var d = t.dataset;
      if(d.pkm != null){ var m = parseFloat(t.value); if(!isNaN(m)) PK.rows[+d.pkm][6] = m / 100; if(PK.st !== "draft") PK.st = "draft"; render(); return true; }
      if(d.pk){
        if(d.pk === "min") PK.minMargin = +t.value || 0;
        else if(d.pk === "row") PK.showRow = +t.value;
        else if(d.pk === "lines") PK.lines = t.checked;
        else PK[d.pk] = t.value;
        render(); return true;
      }
      if(d.plsw){ PL.off[d.plsw] = !t.checked; toast(t.checked ? "เปิดขายที่สาขานี้แล้ว (mock)" : "ปิดบริการที่สาขานี้ · หน้ารับฝากของสาขาจะไม่แสดงบริการนี้ (mock)"); render(); return true; }
      return false;
    }

