    function csAfter(){ var a = document.getElementById("csPayQr"), b = document.getElementById("csPieceQr"); if(a) drawQr(a, "pay" + CS.docs.track); if(b) drawQr(b, CS.docs.ship + "-1"); var q = document.getElementById("csQ"); if(q && !CS.err) setTimeout(function(){ q.focus(); }, 30); }
    function csScanDo(v){
      var q = String(v || CS.q || "").trim().toUpperCase(), r = q ? ctrFind(q) : null;
      CS.q = "";
      if(!r){ CS.err = "ไม่พบรหัสนี้ ตรวจรหัสบนหน้าจอลูกค้าอีกครั้ง"; return; }
      CS.err = null;
      if(r.kind === "paid"){ CS.drop = { rec:r, g:Math.round(r.kg * 1000), extraPaid:null, at:null }; CS.rec = null; return; }
      if(r.done){ CS.rec = r; CS.d = r.state; CS.docs = r.done; return; }
      csOpen(r);
    }
    function csClick(a, b){
      if(a !== "cs") return false;
      var op = b.dataset.cs, v = b.getAttribute("data-v"), d = CS.d;
      switch(op){
        case "login": CS.login = true; break;
        case "logout": CS.login = false; CS.pass = ""; CS.rec = null; CS.docs = null; CS.drop = null; break;
        case "qr": toast("QR สาขา: ลูกค้าสแกนเพื่อเข้าสู่ระบบด้วย LINE (หน้า /counter/branches)"); return true;
        case "print": toast("ส่งไปเครื่องพิมพ์แล้ว (จำลอง)"); return true;
        case "home": CS.docs = null; CS.drop = null; CS.rec = null; CS.step = 0; break;
        case "scan": csScanDo(v || (document.getElementById("csQ") || {}).value); break;
        case "go": CS.step = +v; CS.err = null; break;
        case "itemsedit": toast("แก้ชื่อ จำนวน มูลค่า และ HS ได้จนกว่าจะยืนยัน · บันทึกเป็น counter revision (mock ในหน้านี้)"); return true;
        case "saveweigh": d.g0save = true; d.dirty = false; d.saved = true; if(d.prices.length) d.stale = true; toast("บันทึกที่ชั่ง/วัดแล้ว"); break;
        case "reprice": d.prices.push(csPriceNow()); d.stale = false; d.agreed = null; break;
        case "agree": d.agreed = now(); break;
        case "kycread": d.kyc.card = { title:"นาง", first:d.sName.split(" ")[0], last:d.sName.split(" ").slice(1).join(" "), en:"Mrs. " + (d.sName === "สมหญิง รักไทย" ? "Somying Rakthai" : "Card Holder"), id:"1101700203450", idm:"1-1017-xxxxx-45-0", exp:"12 มี.ค. 2575" }; break;
        case "kycother": d.kyc.card = { title:"นาย", first:"ประยุทธ", last:"มั่นคง", en:"Mr. Prayut Mankong", id:"1101700203450", idm:"1-1017-xxxxx-45-0", exp:"3 ก.ย. 2574" }; break;
        case "kycmanual": d.kyc.form = { id:"", title:"", first:"", last:"", exp:"" }; d.kyc.card = null; break;
        case "kycreset": d.kyc.card = null; d.kyc.form = null; d.kyc.checked = false; break;
        case "kycusename": var c = d.kyc.form || d.kyc.card; d.sName = c.first + " " + c.last; toast("เปลี่ยนชื่อผู้ส่งเป็นชื่อตามบัตรแล้ว"); break;
        case "kycok": var cc = d.kyc.form || d.kyc.card; d.kyc.card = { first:cc.first, last:cc.last, idm:cc.idm || (cc.id.slice(0, 1) + "-" + cc.id.slice(1, 5) + "-xxxxx-" + cc.id.slice(10, 12) + "-" + cc.id.slice(12)), exp:cc.exp, entry:d.kyc.form ? "เจ้าหน้าที่กรอกเอง" : "" }; d.kyc.form = null; d.kyc.st = "verified"; break;
        case "redit": d.editR = true; d.rPhoneDraft = d.rPhone; break;
        case "rcancel": d.editR = false; break;
        case "rsave": d.rPhone = d.rPhoneDraft; d.editR = false; if(d.prices.length) d.stale = true; break;
        case "toast": toast(v); return true;
        case "create":
          flConfirm("ส่ง " + CS.rec.code + " เข้าระบบ D-Post Inter?", "ระบบจะคิดราคาใหม่จากข้อมูลที่เคาน์เตอร์ แล้วสร้างรายการส่งจริงพร้อมเลขติดตาม", "สร้าง shipment", function(){
            var todo = csTodo(), r = CS.rec;
            if(todo.length){ CS.err = d.kyc.st !== "verified" ? "ยังไม่ได้ยืนยันตัวตนผู้ส่ง — อ่านบัตรประชาชนก่อน" : todo[0][0]; render(); csAfter(); return; }
            CS.err = null;
            CS.docs = { track:fsTrack({ code:r.agentCode, prov:r.prov }, r.cc), ship:r.shipId, pickup:String(980000 + Math.floor(Math.random() * 9999)), paid:false };
            r.done = CS.docs; r.state = d; r.accepted = true;
            render(); csAfter(); window.scrollTo({ top:0 });
          }); return true;
        case "paid":
          CS.docs.paid = true; CS.docs.paidAt = new Date().getDate() + " " + TH_MONTHS[new Date().getMonth()] + " " + (new Date().getFullYear() + 543) + " " + now();
          var y = new Date().getFullYear() + 543;
          if(typeof FL !== "undefined" && FL.draft && FL.draft.code === CS.rec.code){ FL.counter = true; FL.paid = { receipt:"RC-" + CS.rec.code, track:CS.docs.track, agent:agentTrack({ prov:CS.rec.prov }), product:CS.rec.product, shipId:CS.docs.ship }; if(FL.stage === "ticket") flRender(); }
          break;
        case "dropextra": CS.drop.extraPaid = now(); break;
        case "dropaccept": CS.drop.rec.accepted = true; CS.drop.at = now(); toast("รับฝากแล้ว · อัปเดต Track & Trace"); break;
        case "reprint": toast("ส่ง label " + CS.drop.rec.track + " ไปเครื่องพิมพ์แล้ว (จำลอง)"); return true;
      }
      render(); csAfter(); return true;
    }
    function csChange(t){
      var f = t.dataset.csf, k = t.dataset.csk, d = CS.d;
      if(f === "user" || f === "pass"){ CS[f] = t.value; var bt = document.querySelector('[data-cs="login"]'); if(bt) bt.disabled = !(CS.user && CS.pass); return true; }
      if(f === "q"){ CS.q = t.value.toUpperCase(); t.value = CS.q; return true; }
      if(f === "g"){ d.g = +t.value || 0; d.dirty = true; render(); return true; }
      if(f === "dim"){ d.dims[+t.dataset.i] = +t.value || 0; d.dirty = true; render(); return true; }
      if(f === "dg"){ CS.drop.g = +t.value || 0; render(); return true; }
      if(f === "rPhone"){ d.rPhoneDraft = t.value; return true; }
      if(k){ if(k === "checked") d.kyc.checked = t.checked; else d.kyc.form[k] = t.value; render(); var el = document.querySelector('[data-csk="' + k + '"]'); if(el && k !== "checked"){ el.focus(); el.setSelectionRange(el.value.length, el.value.length); } return true; }
      return false;
    }

