    function ctCell(v, avg, fmt){ var cls = v >= avg * 1.05 ? " ct-up" : v < avg * .8 ? " ct-dn" : ""; return '<td class="n' + cls + '">' + fmt(v) + '</td>'; }

    /* rows = [[name, base per day, sub?]] → table of name × periods, coloured vs the same-period average */
