    /* ---------------- events ---------------- */
    function v11Click(a, b){
      if(a !== "v11") return false;
      var k = b.dataset.k, v = b.getAttribute("data-v");
      switch(k){
        case "gm": V.geo.m = v; break; case "gseg": V.geo.seg = v; break; case "gsel": V.geo.sel = v; break;
        case "rcell": var p = v.split(":"); if(V.rfm.r === +p[0] && V.rfm.f === +p[1]){ V.rfm.r = 0; V.rfm.f = 0; } else { V.rfm.r = +p[0]; V.rfm.f = +p[1]; } V.rfm.seg = ""; V.rfm.n = 30; break;
        case "rseg": V.rfm.seg = V.rfm.seg === v ? "" : v; V.rfm.r = 0; V.rfm.f = 0; V.rfm.n = 30; break;
        case "r": case "f": case "m": V.rfm[k] = +v; V.rfm.n = 30; break;
        case "rclr": V.rfm = { r:0, f:0, m:0, seg:"", n:30 }; break;
        case "rmore": V.rfm.n += 30; break;
        case "cdp": V.cdp.p = +v; break;
        case "cust": A.cust = v; if(A.page !== "customers"){ nav("customers"); return true; } window.scrollTo({ top:0 }); break;
        case "cback": A.cust = null; break;
        case "ct": V.ct = v; V.cn = 25; break; case "cmore": V.cn += 25; break;
        case "ctog": var fl = flags(custOf(A.cust)); fl[v] = !fl[v]; toast("บันทึกแล้ว"); break;
        case "ship": A.shipId = v; if(A.page !== "ships"){ nav("ships"); return true; } window.scrollTo({ top:0 }); break;
        case "sback": A.shipId = null; break;
        case "sf": V.sf = v; break;
        case "copy": try{ navigator.clipboard.writeText(v).then(function(){ toast("คัดลอก " + v + " แล้ว"); }, function(){ toast(v); }); }catch(e){ toast(v); } return true;
        case "annnew": V.annNew = !V.annNew; break;
        case "anntog": ANNS.forEach(function(x){ if(x.id === v) x.on = !x.on; }); annHidden = false; annRender(); toast("อัปเดตแถบประกาศแล้ว"); break;
        case "annview": annOpen(v); return true;
      }
      render(); return true;
    }
    function v11Change(t){
      var d = t.dataset.v11; if(!d) return false;
      if(d === "sq"){ V.sq = t.value; render(); var e = document.getElementById("v11sq"); if(e){ e.focus(); e.setSelectionRange(e.value.length, e.value.length); } return true; }
      if(d === "cq"){ V.cq = t.value; V.cn = 25; render(); var e2 = document.getElementById("v11cq"); if(e2){ e2.focus(); e2.setSelectionRange(e2.value.length, e2.value.length); } return true; }
      if(d === "sag" || d === "scc"){ V[d] = t.value; render(); return true; }
      if(d === "cf"){ flags(custOf(A.cust))[t.dataset.k] = t.value; toast("บันทึกแล้ว"); return true; }
      return false;
    }
    function v11Adm(P){
      P.geo = pgGeo; P.rfm = pgRfm; P.cdp = pgCdp; P.ann = pgAnn; P.customers = pgCust2; P.ships = pgShips2;
      AD.addEventListener("submit", function(e){
        if(e.target.id !== "annForm") return; e.preventDefault();
        var tt = document.getElementById("annT").value.trim(), body = document.getElementById("annB").value.trim(); if(!tt) return;
        ANNS.unshift({ id:"n" + Date.now(), on:false, aud:document.getElementById("annA").value, from:document.getElementById("annF").value || "2026-11-05", to:document.getElementById("annE").value || "2026-11-30", tag:document.getElementById("annG").value, title:tt, short:tt,
          body:function(){ return '<p>' + esc(body || tt).replace(/\n/g, "<br>") + '</p>'; } });
        V.annNew = false; render(); toast("บันทึกประกาศแล้ว · กด เปิดแสดง เพื่อขึ้นแถบ");
      });
      var tm; AD.addEventListener("input", function(e){ var t = e.target; if(t.dataset.v11 === "sq" || t.dataset.v11 === "cq"){ clearTimeout(tm); tm = setTimeout(function(){ v11Change(t); }, 250); } });
    }
