    function saWrap(html){ return '<div class="sa-pg">' + html + '</div>' + saModalHtml(); }
    function saConfirm(title, body, ok, fn, danger){ saMOpen({ t:"confirm", title:title, body:body, ok:ok, fn:fn, danger:danger !== false }); }
