      var holdC = '<div class="ad-card"><label class="sa-chk sa-holdchk"><input type="checkbox" data-si="rf" data-f="hold" data-re="1"' + (rf.hold ? " checked" : "") + '>' + ic("alert") + '<span>ติดธงสินค้าต้องห้าม / ต้องตรวจ (ระงับพัสดุ)</span></label>' +
        (rf.hold ? '<div class="sa-grid2 sa-mt">' + saFld("เหตุผล (ภายใน) *", saTa("rf", "hr1", rf.hr1, { id:"saRf_hr1", max:500 }), "", e.hr1) +
          saFld("เหตุผลที่ลูกค้าเห็น", saTa("rf", "hr2", rf.hr2, { id:"saRf_hr2", max:300 }), "เว้นว่างได้ ลูกค้าจะเห็นข้อความ “ติดต่อทีมงาน”") + '</div>' : '') +
        saFld("หมายเหตุภายใน", saTa("rf", "note", rf.note, { max:1000 })) + '</div>';
