      var keys = [["ไปช่องถัดไป (สแกนเนอร์ส่ง Enter ให้เอง)", "Enter"], ["บันทึก", "Ctrl + Enter"], ["กลับไปช่องสแกน tracking", "F2"], ["ถ่ายภาพ (ในหน้าต่างกล้อง)", "Space"], ["ปิดหน้าต่างกล้อง", "Esc"]];
