      s.ps.forEach(function(p){ if(p.pre && p.pre.items.length){ var c = p.pre.cur || SI.CUR[p.cc]; cur[c] = (cur[c] || 0) + p.pre.items.reduce(function(a, x){ return a + x[1] * x[2]; }, 0); } });
      var decl = Object.keys(cur).map(function(c){ return SI.FX[c] ? SI.fx(cur[c], c) : c + " " + cur[c]; }).join(" · ");
      var act = saB({ k:"manifest", t:"ดาวน์โหลด Manifest (Excel)", ic:"dl" }) + (saCan("invoice.manage") && b.st === "ARRIVED" ? saB({ k:"gen", t:"ออกใบแจ้งหนี้", ic:"doc", cls:"pri" }) : '');
      var kp = '<div class="ad-kpis">' + kpi("จำนวนชิ้น", nf(s.n), null, "", "ชิ้น") + kpi("น้ำหนักจริงรวม", SI.kg(s.g)) + kpi("น้ำหนักคิดเงินรวม", SI.kg(s.cg)) + kpi("ลูกค้า", nf(s.nc), decl ? ["มูลค่าสำแดง: " + decl, ""] : null, "", "คน") + '</div>';
      var add = "";
