      return { cc:cc, mode:mode, perKg:r ? saMajor(r.perKg) : "", firstKg:r && r.firstKg ? saMajor(r.firstKg) : "", min:r ? saMajor(r.min) : "", step:r ? String(r.step) : "1", div:r && r.div ? String(r.div) : "",
        from:saDay(saNow()), promo:false, pPer:"", pMin:"", pEnd:"", note:"", err:"" };
