    function saRdSave(){
      var d = SA.rd, today = saDay(saNow()), per = saMoney(d.perKg), first = d.firstKg.trim() ? saMoney(d.firstKg) : null, min = d.min.trim() ? saMoney(d.min) : per, step = +d.step || 1, div = d.div.trim() ? +d.div : null;
      d.err = "";
      if(!d.from || d.from < today) d.err = "วันที่มีผลต้องไม่อยู่ในอดีต";
      else if(!(per > 0) || (first != null && !(first > 0)) || isNaN(min) || !(step >= 1 && step <= 10000) || (div != null && !(div >= 1000 && div <= 10000))) d.err = "ตรวจสอบตัวเลข: ราคามากกว่า 0, ปัดน้ำหนัก 1–10,000 กรัม, ตัวหาร 1,000–10,000 หรือเว้นว่าง";
      var pPer = null, pMin = null;
      if(!d.err && d.promo){
        pPer = saMoney(d.pPer); pMin = d.pMin.trim() ? saMoney(d.pMin) : null;
        if(!d.pEnd || d.pEnd < d.from) d.err = "วันสุดท้ายของโปรต้องไม่ก่อนวันที่มีผล";
        else if(!(pPer > 0) || pPer >= per) d.err = "ราคาโปรต้องต่ำกว่าราคาเต็ม";
        else if(pMin != null && (isNaN(pMin) || pMin > min)) d.err = "ขั้นต่ำช่วงโปรต้องไม่สูงกว่าขั้นต่ำปกติ";
      }
      if(d.err){ render(); return; }
      var h = { cc:d.cc, mode:d.mode, perKg:per, firstKg:first, min:min, step:step, div:div, from:d.from + "T00:00:00+07:00", to:"", note:d.note.trim(), pPer:pPer, pMin:pMin, pEnd:d.promo ? d.pEnd : "" };
      SA.rateHist.forEach(function(x){ if(x.cc === d.cc && x.mode === d.mode && !x.to && saDay(x.from) <= d.from) x.to = h.from; });
      SA.rateHist.unshift(h);
      if(d.from <= today){
        var r = SI.rate(d.cc, d.mode);
        if(!r){ r = { cc:d.cc, mode:d.mode, eta:"" }; SI.RATES.push(r); }
        r.perKg = per; r.firstKg = first; r.min = min; r.step = step; r.div = div; h.card = r;
      }
      saAudit("rateCard.create", "RateCard", d.cc + "-" + d.mode, [["pricePerKgSatang", "", String(per)], ["effectiveFrom", "", d.from]]);
      SA.rd = null; SI.changed(); toast("สร้างอัตราใหม่แล้ว");
    }
