    function onInput(e){
      var t = e.target;
      if(t.dataset.csf === "user" || t.dataset.csf === "pass" || t.dataset.csf === "q" || t.dataset.csf === "rPhone"){ csChange(t); return; }
      if(t.id === "rqC" || t.id === "rqP" || t.id === "rqX"){ rfqCalc(); return; }
      if(t.dataset.edit){ if(!t._ed){ t._ed = 1; POS.edits++; POS.s.log.push(["วันนี้ " + now(), "แก้ไข " + t.dataset.edit + " ที่เคาน์เตอร์", "POS-HLS-03"]); } if(t.dataset.edit === "HS Code") POS.s.hs = t.value; if(t.dataset.edit === "ผู้รับ") POS.s.rcv = t.value; return; }
    }
    function onChange(e){
      var t = e.target, d = t.dataset;
      if(t.id === "adMnav"){ nav(t.value); return; }
      if(siChange(t) || v11Change(t) || f12Change(t) || v4Change(t) || csChange(t)) return;
      if(d.act === "upfile" && t.files && t.files[0]){ UP.loaded = true; UP.fixed = {}; UP.done = false; UP.fname = t.files[0].name + " (ตรวจด้วยข้อมูลตัวอย่าง)"; render(); return; }
      if(d.pos){ if(d.pos === "ins" || d.pos === "plus") POS[d.pos] = t.checked; else if(d.pos === "insV") POS.insV = +t.value || 0; else POS.promo = t.value; render(); return; }
      if(d.wk){ POS.wk[d.wk] = d.wk === "kg" ? +t.value || 0 : t.value; render(); return; }
      if(d.px){ if(d.px === "reg" || d.px === "pod") PX[d.px] = t.checked; else if(d.px === "start" || d.px === "qty") PX[d.px] = Math.max(1, Math.min(d.px === "qty" ? 12 : 99999999, +t.value || 1)); else PX[d.px] = t.value; render(); return; }
      if(d.sim){ SIM[d.sim] = d.sim === "remote" ? t.checked : /kg|l|w|h/.test(d.sim) && d.sim.length <= 2 ? +t.value || 0 : t.value; render(); return; }
      if(d.clv){ CLV[d.clv] = +t.value || 0; render(); return; }
      if(d.pb){ PB[d.pb] = /disc|min/.test(d.pb) ? +t.value || 0 : t.value; PB.test = null; render(); return; }
      if(d.camp){ camps[+d.camp].st = t.checked ? "on" : "off"; toast(t.checked ? "เปิดแคมเปญแล้ว" : "หยุดแคมเปญแล้ว"); return; }
      if(d.route){ var r = ROUTE[+d.route], old = r[1]; r[1] = t.value; var L = document.getElementById("rtLog"); if(L){ var x = document.createElement("div"); x.innerHTML = '<span class="d">' + now() + '</span> ' + CC[r[0]] + ': ' + old + ' → <span class="ok">' + t.value + '</span> · มีผลทันที'; L.appendChild(x); } toast(CC[r[0]] + " ใช้ " + t.value + " แล้ว"); return; }
      if(d.routeon){ ROUTE[+d.routeon][2] = t.checked; toast("DDP " + CC[ROUTE[+d.routeon][0]] + (t.checked ? " เปิดใช้" : " ปิดใช้")); return; }
      if(d.mt){ MT[d.mt] = t.value; render(); return; }
      if(d.mtaud){ MT.aud[d.mtaud] = t.checked; render(); return; }
    }
    function onKey(e){
      if(e.key !== "Enter") return;
      var id = e.target.id;
      if(id === "adQ"){ A.q = e.target.value; render(); }
      if(id === "posQ") posScanGo(e.target.value);
      if(id === "csQ"){ e.preventDefault(); CS.q = e.target.value; csClick("cs", { dataset:{ cs:"scan" }, getAttribute:function(){ return null; } }); return; }
      if(id === "ctrQ") v4Click("ctr", { dataset:{ op:"scan" }, getAttribute:function(){ return null; } });
      if(id === "hsQ"){ A.hsq = e.target.value; render(); }
      if(id === "ruleQ"){ A.ruleq = e.target.value; render(); }
    }
    [AD, document.getElementById("adDrawer")].forEach(function(root){
      root.addEventListener("click", onClick); root.addEventListener("input", onInput); root.addEventListener("change", onChange); root.addEventListener("keydown", onKey);
    });
    document.getElementById("adNav").addEventListener("click", onClick);
    document.getElementById("adMnav").addEventListener("change", onChange);
    document.getElementById("adDrawer").addEventListener("click", function(e){ if(e.target.closest("[data-drx]")) closeShip(); });
    document.addEventListener("keydown", function(e){ if(e.key === "Escape") closeShip(); });

