    function addAq(o){
      decl.unshift(["ฟาร์มปลากัดสามพราน", o.items.map(function(x){ return x[0]; }).join(", "), "ถุง/กล่อง", o.items.reduce(function(a, x){ return a + (+String(x[1]).replace(/,/g, "") || 0); }, 0), o.boxes + " กล่อง · " + o.track]);
      rounds[0][4] = Math.min(rounds[0][5], rounds[0][4] + o.boxes); rounds[0][6]++;
      permits.unshift(["PM-" + o.track.slice(2, 8), "กรมประมง", "ร.9 · Health Cert · DOF4 · DOF11 · Self-cert" + (o.cc === "CN" ? " · GACC" : ""), "ฟาร์มปลากัดสามพราน", o.docMode === "thp" ? 1 : 0]);
      var sh = ships.filter(function(x){ return x.tr === o.track; })[0]; if(sh){ sh.st = "doc"; sh.cust = "ฟาร์มปลากัดสามพราน"; sh.item = o.items.map(function(x){ return x[0] + " " + x[1]; }).join(", "); }
      refreshNav();
    }
    function addPermit(o){
      permits.unshift(["PM-" + o.track.slice(2, 8), o.agency, o.doc, o.cust, 0]);
      var sh = ships.filter(function(x){ return x.tr === o.track; })[0]; if(sh){ sh.st = "doc"; sh.cust = o.cust; sh.item = o.item; }
      refreshNav();
    }
    return { va:function(v){ va.unshift(v); refreshNav(); if(A.page === "quotes") render(); }, add:addLive, aq:addAq, permit:addPermit, render:function(){ refreshNav(); render(); }, nav:nav, staff:setStaff };
